import {NPC} from "@/YellowSubmarine/npcs/NPC";
import {CylindricalDetectionZone} from "@/YellowSubmarine/detection system/CylindricalDetectionZone";
import {CameraConfiguration} from "@/YellowSubmarine/camera system/CameraConfiguration";
import {Angle, Color3, PBRMaterial, Vector3} from "@babylonjs/core";
import {CartoonShaderMaterial} from "@/YellowSubmarine/shader material/CartoonShaderMaterial";
import {DialogueNodeChainingBuilder} from "@/YellowSubmarine/dialogue system/DialogueNodeChainingBuilder";
import {JournalUI} from "@/YellowSubmarine/quest system/ui/JournalUI";
import {QuestManager} from "@/YellowSubmarine/quest system/QuestManager";
import {SimpleDialogueNode} from "@/YellowSubmarine/dialogue system/nodes/SimpleDialogueNode";
import {ActionDialogueNode} from "@/YellowSubmarine/dialogue system/nodes/ActionDialogueNode";
import {BBTextBuilder} from "@/YellowSubmarine/BBCode/builders/BBTextBuilder";
import {BoldTag} from "@/YellowSubmarine/BBCode/tags/BoldTag";
import {FirstTimeDialogueNode} from "@/YellowSubmarine/dialogue system/nodes/FirstTimeDialogueNode";
import {ItalicTag} from "@/YellowSubmarine/BBCode/tags/ItalicTag";
import {ColorTag} from "@/YellowSubmarine/BBCode/tags/ColorTag";
import {loadMesh} from "@/YellowSubmarine/Utils";
import {ConditionalDialogueNode} from "@/YellowSubmarine/dialogue system/nodes/ConditionalDialogueNode";
import {MirrorPuzzle} from "@/YellowSubmarine/mirror puzzle/MirrorPuzzle";
import {TempleBall} from "@/YellowSubmarine/temple/TempleBall";
import {Submarine} from "@/YellowSubmarine/Submarine";

export class NPCFactory {

    public static async createPedro(): Promise<NPC>{
        const pedro = new NPC();
        pedro.name = "Pedro";
        loadMesh("models/characters/pedro.glb").then((result) => {
            pedro.mesh = result.meshes[0];
            result.meshes.forEach((mesh) => {
                const mat = mesh.material as PBRMaterial;
                if(mat){
                    const toonMat = new CartoonShaderMaterial();
                    toonMat.assignMaterial(mesh).then(() => {
                        toonMat.configureFromPBRMaterial(mat);
                    });
                }
            })
        });
        pedro.detectionZone = new CylindricalDetectionZone( {
            height: 8,
            diameterTop: 100,
            diameterBottom: 100,
        }, true);

        pedro.detectionZone.zone.position.set(0, -11, 0);
        pedro.dialogue = DialogueNodeChainingBuilder
            .createNewDialogueBuilder(SimpleDialogueNode,new BBTextBuilder().addText("OH CA VA PAS DE ME REVEILLER COMME CA ! MAIS QUI ES TU !!", BoldTag).build() )
            .chainNode(SimpleDialogueNode, "Ca fais bien longtemps que j'ai pas vu quelqu'un comme toi ici ! Je me présente, je suis Pedro. Je pêche ici depuis bel lurette mon n'veu.")
            .chainNode(SimpleDialogueNode, new BBTextBuilder().addText("Ici, eh beh ici je sais pas trop comment te le décrire. C'est assez").addText("vide", ItalicTag).addText("et ça mord pas trop au bout de ma canne...").build() )
            .chainNode(SimpleDialogueNode, new BBTextBuilder().addText("Mais ! Y'a un").addText("p'tit endroit au nord d'ici", ColorTag, "blue").addText("un peu particulier.").build())
            .chainNode(SimpleDialogueNode, new BBTextBuilder().addText("Y'avait deux boules et plein de poteaux", ColorTag, "blue").addText(", j'ai pas tout compris et j'étais fatigué Ducoup j'suis parti..").build())
            .chainNode(SimpleDialogueNode, "Normalement tu devrais l'apercevoir d'ici ! Fais attention ! ")
            .chainNode(SimpleDialogueNode, new BBTextBuilder().addText("Aussi !").addText("Information capital !!!", BoldTag).addText("Si tu as un journal dans ton sous-marin").addText("tu peux prendre des notes",BoldTag).addText("sur tout ce que tu vas découvrir pour ne pas oublier d'information").build())
            .chainNode(SimpleDialogueNode, new BBTextBuilder().addText("Hésite pas à aller voir").addText("les habitants des autres îles", BoldTag, ColorTag, "blue").addText(", ils devraient pouvoir t'aider !").build())
            .chainNode(SimpleDialogueNode, "Bon aller moi je retourne pêcher (et dormir au passage... ça fais bieeeen ..... loongt.... ZzZz)")
            .chainNode(FirstTimeDialogueNode)
            .chainNode(ActionDialogueNode, true,"Mise à jour de la quête",() => {
                JournalUI.instance.addEntryToQuest(QuestManager.instance.getQuest("dreamland"), "Pedro s'est endormie");
                JournalUI.instance.addEntryToQuest(QuestManager.instance.getQuest("dreamland"), "Il y aurait un endroit interessant au nord de l'ile des dauphins");
                JournalUI.instance.addEntryToQuest(QuestManager.instance.getQuest("dreamland"), "Deux boules ? seraient déjà présentes");
                JournalUI.instance.addEntryToQuest(QuestManager.instance.getQuest("dreamland"), "Vu le manque de place, je vais pouvoir en prendre qu'une seule à la fois..");

                QuestManager.instance.getQuest("dreamland")?.updateCurrentStepStatus();
            }, undefined)
            .setDialogueProvider(pedro).build();

        pedro.cameraConfiguration = new CameraConfiguration();
        pedro.cameraConfiguration.target = pedro.transformNode;
        pedro.cameraConfiguration.distanceFromTarget = 10;
        pedro.cameraConfiguration.offset = Vector3.Up().scale(2);
        pedro.cameraConfiguration.wantedAlpha = Angle.FromDegrees(-90).radians();

        return pedro;
    }

    public static async createFox(): Promise<NPC>{
        const fox = new NPC();
        fox.name = "Crimson";
        loadMesh("models/characters/fox.glb").then((result) => {
            fox.mesh = result.meshes[0];
            result.meshes.forEach((mesh) => {
                const mat = mesh.material as PBRMaterial;
                if(mat){
                    const toonMat = new CartoonShaderMaterial();
                    toonMat.assignMaterial(mesh).then(() => {
                        toonMat.configureFromPBRMaterial(mat);
                    });
                }
            })
        });
        fox.detectionZone = new CylindricalDetectionZone( {
            height: 8,
            diameterTop: 45,
            diameterBottom: 45,
        }, true);

        fox.dialogue = DialogueNodeChainingBuilder
            .createNewDialogueBuilder(SimpleDialogueNode, new BBTextBuilder().addText("Je sais pas si tu vois la même chose que moi").addText("(peut-être que c'est un mirage).",ItalicTag).addText("Y'a une").addText("piste de bowling là-bas",BoldTag).addText("où y'a les quilles qui sortent de l'eau.").build())
            .chainNode(SimpleDialogueNode, "Y'a une sorte de boule de bowling qui était sur l'île. J'ai essayé de jouer avec des quilles en glace mais ça a pas trop marché.")
            .chainNode(SimpleDialogueNode, "Parmi les quilles j'ai mis une bouteille que j'ai trouvée dans le coin et bizarrement, quand j'ai fait un STRIKE ! Y'a une note qui est sortie.")
            .chainNode(SimpleDialogueNode, new BBTextBuilder().addText("Y'avait marqué ça :").addText("« Redina, la plus forte, restait en retrait afin de couvrir leurs arrières »",ColorTag,"blue").build())
            .chainNode(SimpleDialogueNode, new BBTextBuilder().addText("Bizarre l'ambiance... J'en ai marre de jouer au bowling donc").addText("j'te donne la boule !",BoldTag).addText("Mais prends-en soin !").build())
            .chainNode(SimpleDialogueNode, "Allez, je vais jouer à la pétanque moi...")
            .chainNode(ActionDialogueNode, "Mise à jour de la quête",() => {
                JournalUI.instance.addEntryToQuest(QuestManager.instance.getQuest("dreamland"), "D'après Crimson : Redina, la plus forte, restait en retrait afin de couvrir leurs arrières");
            }, undefined)
            .setDialogueProvider(fox).build();

        fox.cameraConfiguration = new CameraConfiguration();
        fox.cameraConfiguration.target = fox.transformNode;
        fox.cameraConfiguration.distanceFromTarget = 10;
        fox.cameraConfiguration.wantedAlpha = Angle.FromDegrees(-90).radians();

        return fox;
    }

    public static async createGirl(): Promise<NPC>{
        const scientific = new NPC();
        scientific.name = "Rosa";
        loadMesh("models/characters/phare_girl.glb").then((result) => {
            scientific.mesh = result.meshes[0];
            result.meshes.forEach((mesh) => {
                const mat = mesh.material as PBRMaterial;
                if(mat){
                    const toonMat = new CartoonShaderMaterial();
                    toonMat.assignMaterial(mesh).then(() => {
                        toonMat.configureFromPBRMaterial(mat);
                    });
                }
            })
        });
        scientific.detectionZone = new CylindricalDetectionZone( {
            height: 8,
            diameterTop: 45,
            diameterBottom: 45,
        }, true);


        const dialogueBuilder = DialogueNodeChainingBuilder
            .createNewDialogueBuilder(ConditionalDialogueNode, () => MirrorPuzzle.instance.hasBeenSolved)

        const beforeQuestIsDone = dialogueBuilder
            .chainNode(SimpleDialogueNode, false,"Si je suis la trajectoire de cette étoile, alors je peux peut-être réussir à démontrer que e = m6 !")
            .chainNode(SimpleDialogueNode,new BBTextBuilder().addText("Oh salut toi ! T'as un sacré sous-marin !").addText("J'adore",ItalicTag).addText("les sous-marins tu tombes à pic !").build())
            .chainNode(SimpleDialogueNode,"j'ai besoin de ton aide pour résoudre réparer mon phare.")
            .chainNode(SimpleDialogueNode,"Tout ce que tu as à faire c'est tourner les mirroirs pour que la lumière les atteint tous puis revient au phare.")
            .chainNode(SimpleDialogueNode,new BBTextBuilder().addText("Par contre tu verras le mécanisme est curieux.").build())
            .chainNode(SimpleDialogueNode,new BBTextBuilder().addText("Tourner un mirroir ").addText("peut ou non en faire tourner un autre", BoldTag).build())
            .chainNode(SimpleDialogueNode,"Mais bon je suis sûre que tu y arriveras.")
            .chainNode(SimpleDialogueNode,"Reviens me voir quand c'est fait d'accord. J'ai une récompense pour toi !")

        const afterQuestIsDone = dialogueBuilder
            .chainNode(SimpleDialogueNode, true, "Merci bcp. tu m'as vraiment sauvé sur ce coup la.")
            .chainNode(SimpleDialogueNode,"Pour la peine, je vais te présenter les conclusions de mon expérience, prépare toi à en prendre plein la vue !")
            .chainNode(SimpleDialogueNode,new BBTextBuilder().addText("J'ai trouvé").addText("une boule de couleurs avec deux parchemins.",ColorTag,"blue").addText("Commençons par les FAITS !").build())
            .chainNode(SimpleDialogueNode,new BBTextBuilder().addText("Fait numéro 1 : la boule est").addText("d'une couleur spécifique...",BoldTag).addText("Hmmmm...... Ok soit.").build())
            .chainNode(SimpleDialogueNode,new BBTextBuilder().addText("Fait numéro 2 : les textes parlent de...je ne sais pas trop quoi à vrai dire. Mais ! J'ai l'impression que ").addText("les couleurs sont importantes !",BoldTag).build())
            .chainNode(SimpleDialogueNode,"Fait numéro 3 : les deux parchemins racontes la chose suivante : ")
            .chainNode(SimpleDialogueNode,new BBTextBuilder().addText("Greina, la plus sage, veillait sur ses soeurs sans faillire à sa tâche",ColorTag,"blue").build())
            .chainNode(SimpleDialogueNode,new BBTextBuilder().addText("Bluella, la plus téméraire, ouvrait la marche, portant un chapeau violet",ColorTag,"blue").build())
            .chainNode(SimpleDialogueNode,"Maintenant, passons à la THEORIE !")
            .chainNode(SimpleDialogueNode,"Théorie numéro 1 : une boule de couleur a une position unique. Mais où ??? AHHH Je ne comprends pas....")
            .chainNode(SimpleDialogueNode,new BBTextBuilder().addText("Théorie numéro 2 : Si la théorie 1 est correcte, alors la solution du puzzle doit dépendre de ses boules et ").addText("EST UNIQUE.",BoldTag).build())
            .chainNode(SimpleDialogueNode,"Et voilà c'est un peu tout ce que j'ai, je suis dans une sacrée impasse. Je vais sûrement rater le prix Nobel cette année...")
            .chainNode(FirstTimeDialogueNode)
            .chainNode(ActionDialogueNode,true, "Allez j'te laisse la boule, je suis passé à autre chose ! Tu me diras une prochaine fois si ça t'a été utile !", () => {
                const ball = new TempleBall(scientific.transformNode.absolutePosition.add(new Vector3(-30,20,-30)), Color3.Blue());

                if(!Submarine.instance.templeBall){
                    Submarine.instance.grabBall(ball);
                }
            }, false)
            .chainNode(SimpleDialogueNode,"À la revoyure !")
            .chainNode(ActionDialogueNode, "Mise à jour de la quête", () => {
                JournalUI.instance.addEntryToQuest(QuestManager.instance.getQuest("dreamland"), ("Rosa a trouvée ces deux phrases :" +
                    "\n Bluella, la plus téméraire, ouvrait la marche, portant un chapeau violet" +
                    "\n Greina, la plus sage, veillait sur ses soeurs sans faillire à sa tâche"));


            }, undefined)

        scientific.dialogue = dialogueBuilder.setDialogueProvider(scientific).build();

        scientific.cameraConfiguration = new CameraConfiguration();
        scientific.cameraConfiguration.target = scientific.transformNode;
        scientific.cameraConfiguration.distanceFromTarget = 40;
        scientific.cameraConfiguration.wantedAlpha = Angle.FromDegrees(-120).radians();
        scientific.cameraConfiguration.wantedBeta = Angle.FromDegrees(50).radians();

        return scientific;
    }

    public static async createScribe(): Promise<NPC>{
        const scribe = new NPC();
        scribe.name = "Marcel";
        loadMesh("models/characters/scribe.glb").then((result) => {
            scribe.mesh = result.meshes[0];
            result.meshes.forEach((mesh) => {
                const mat = mesh.material as PBRMaterial;
                if(mat){
                    const toonMat = new CartoonShaderMaterial();
                    toonMat.assignMaterial(mesh).then(() => {
                        toonMat.configureFromPBRMaterial(mat);
                    });
                }
            })
        });
        scribe.detectionZone = new CylindricalDetectionZone( {
            height: 8,
            diameterTop: 45,
            diameterBottom: 45,
        }, true);

        scribe.dialogue = DialogueNodeChainingBuilder
            .createNewDialogueBuilder(SimpleDialogueNode, "Que penses-tu de mon prochain poème jeune étranger ?")
            .chainNode(SimpleDialogueNode,new BBTextBuilder().addText("Ballade d’un Génie Naufragé", BoldTag).build())

            .chainNode(SimpleDialogueNode,new BBTextBuilder().addText("Je suis ce grand Marcel, qu’aucun vent ne dérange", ItalicTag).build())
            .chainNode(SimpleDialogueNode,new BBTextBuilder().addText("Poète illustre et fier, perdu sur cet étrange",ItalicTag).build())
            .chainNode(SimpleDialogueNode,new BBTextBuilder().addText("Territoire obscur, bordé par l’inconnu,",ItalicTag).build() )
            .chainNode(SimpleDialogueNode,new BBTextBuilder().addText("Où des piliers sans fin soutiennent l’absolu.",ItalicTag).build() )

            .chainNode(SimpleDialogueNode,new BBTextBuilder().addText("Je ne sais point comment j’ai pu atterrir ici,",ItalicTag).build())
            .chainNode(SimpleDialogueNode,new BBTextBuilder().addText("Mais l’endroit me salue d’un silence exquis.",ItalicTag).build())
            .chainNode(SimpleDialogueNode,new BBTextBuilder().addText("Tantôt le ciel s’emplit de choses voltigeantes,",ItalicTag).build())
            .chainNode(SimpleDialogueNode,new BBTextBuilder().addText("Tantôt le vide plane, en formes déchirantes.",ItalicTag).build())

            .chainNode(SimpleDialogueNode,new BBTextBuilder().addText("Sur le rivage nu, comme un don du destin,", ItalicTag).build())
            .chainNode(SimpleDialogueNode,new BBTextBuilder().addText("J’aperçus une orbe, d’un éclat si divin",ItalicTag).build())
            .chainNode(SimpleDialogueNode,new BBTextBuilder().addText("Que mon esprit, troublé par tant de magnificence,",ItalicTag).build())
            .chainNode(SimpleDialogueNode,new BBTextBuilder().addText("Faillit se noyer dans sa propre éloquence.",ItalicTag).build())

            .chainNode(SimpleDialogueNode,new BBTextBuilder().addText("Juste à côté dormait, message dans bouteille,",ItalicTag).build())
            .chainNode(SimpleDialogueNode,new BBTextBuilder().addText("Un parchemin d’échos, d’une main non pareille.",ItalicTag).build())
            .chainNode(SimpleDialogueNode,new BBTextBuilder().addText("Il était écrit, sans honte ni limite :",ItalicTag).build())
            .chainNode(SimpleDialogueNode,new BBTextBuilder().addText("« Pendant que le soleil était au zénith, Un nuage grisâtre s’approchait depuis l’ouest ».",ColorTag,"blue").build())
            .chainNode(SimpleDialogueNode,"Ah ! Que cette phrase est d’un raffinement leste !")
            .chainNode(SimpleDialogueNode,new BBTextBuilder().addText("Moi seul, Marcel, pouvais en saisir l’essence,",ItalicTag).build())
            .chainNode(SimpleDialogueNode,new BBTextBuilder().addText("Car mon verbe est plus fort que toute connaissance. ",ItalicTag).build())
            .chainNode(SimpleDialogueNode,new BBTextBuilder().addText("Je retourne à présent vers la fontaine noire,",ItalicTag).build())
            .chainNode(SimpleDialogueNode,new BBTextBuilder().addText("Dont l’encre tachera les vers de ma mémoire.",ItalicTag).build())
            .chainNode(SimpleDialogueNode,"Voila ! J'espère que ce ne fut pas un peu trop long.")
            .chainNode(SimpleDialogueNode,"Maintenant file je dois me concentrer !")
            .chainNode(ActionDialogueNode,"Mise à jour de la quête",() => {
                JournalUI.instance.addEntryToQuest(QuestManager.instance.getQuest("dreamland"), "Marcel nous indique dans son poeme interminable : \n " +
                    "Pendant que le soleil était au zénith, Un nuage grisâtre s’approchait depuis l’ouest")
            }, undefined).setDialogueProvider(scribe).build();


        scribe.cameraConfiguration = new CameraConfiguration();
        scribe.cameraConfiguration.target = scribe.transformNode;
        scribe.cameraConfiguration.distanceFromTarget = 10;
        scribe.cameraConfiguration.wantedAlpha = Angle.FromDegrees(150).radians();

        return scribe;
    }

    public static async createRabbit(): Promise<NPC>{
        const rabbit = new NPC();
        rabbit.name = "Matthew";

        loadMesh("models/characters/lapin.glb").then((result) => {
            rabbit.mesh = result.meshes[0];

            result.meshes.forEach((mesh) => {

                const mat = mesh.material as PBRMaterial;
                if(mat){
                    const toonMat = new CartoonShaderMaterial();
                    toonMat.assignMaterial(mesh).then(() => {
                        toonMat.configureFromPBRMaterial(mat);
                    });
                }
            })
        });

        rabbit.detectionZone = new CylindricalDetectionZone( {
            height: 8,
            diameterTop: 45,
            diameterBottom: 45,
        }, true);

        rabbit.detectionZone.zone.position.set(0, -2, 0);

        rabbit.dialogue = DialogueNodeChainingBuilder
            .createNewDialogueBuilder(SimpleDialogueNode,new BBTextBuilder().addText("Trois sœurs, Redina, Greina, Bluella, voyant le nuage s'approcher, se dirigeaient à l'opposée....",ItalicTag, ColorTag, "blue").build())
            .chainNode(SimpleDialogueNode, "Hmmmm... Qu'est-ce que ça peut vouloir dire....")
            .chainNode(SimpleDialogueNode, new BBTextBuilder().addText("AAAAAAAAAAAAAAAAAAAAHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHH",BoldTag,ColorTag, "red").build())
            .chainNode(SimpleDialogueNode, "TU M'AS FAIS PEUR !!!!")
            .chainNode(SimpleDialogueNode, "TIENS PREND ÇA ! ET PARS LOIN D'ICI SANS REVENIR !!!!!!!!!!!!!!!!")
            .chainNode(ActionDialogueNode, "Mise à jour de la quête", () => {
                JournalUI.instance.addEntryToQuest(QuestManager.instance.getQuest("dreamland"), "Marcel nous indique dans son poeme interminable : \n " +
                    " - Trois sœurs, Redina, Greina, Bluella, voyant le nuage s'approcher, se dirigeaient à l'opposée...")
            }, undefined).setDialogueProvider(rabbit).build();



        rabbit.cameraConfiguration = new CameraConfiguration();
        rabbit.cameraConfiguration.target = rabbit.transformNode;
        rabbit.cameraConfiguration.distanceFromTarget = 10;
        rabbit.cameraConfiguration.wantedAlpha = Angle.FromDegrees(-90).radians();

        return rabbit;
    }
}